#import <Foundation/Foundation.h>

@interface LSApplicationWorkspace : NSObject
+ (instancetype)defaultWorkspace;
- (BOOL)openURL:(NSURL *)url;
- (BOOL)openURL:(NSURL *)url withOptions:(NSDictionary *)options;
@end

int main(int argc, char **argv) {
    @autoreleasepool {
        if (argc < 2) { printf("usage: openurl_sim <url>\n"); return 1; }
        NSString *s = [NSString stringWithUTF8String:argv[1]];
        NSURL *url = [NSURL URLWithString:s];
        if (!url) { printf("bad url\n"); return 1; }
        Class cls = NSClassFromString(@"LSApplicationWorkspace");
        LSApplicationWorkspace *ws = [cls performSelector:@selector(defaultWorkspace)];
        if (!ws) { printf("no workspace\n"); return 1; }
        BOOL ok = NO;
        if (argc > 2) {
            NSDictionary *opts = @{
                @"UIApplicationOpenURLOptionsSourceApplicationBundleIdentifierKey": @"im.vector.app",
                @"UIApplicationOpenURLOptionUniversalLinksOnly": @NO,
            };
            ok = [ws openURL:url withOptions:opts];
        } else {
            ok = [ws openURL:url];
        }
        printf("openURL -> %d\n", ok);
    }
    return 0;
}
